// HARDENED: Monotonic generation clock fencing token verification
public boolean writeData(String key, byte[] val, long fencingToken) {
    // Storage engine validates strictly monotonic fencing token before applying mutation
    if (storageEngine.validateAndAdvanceToken(fencingToken)) {
        return storageEngine.write(key, val);
    }
    throw new StaleFencingTokenException("Rejected mutation from superseded leader");
}
